const content = $input.first().json.choices[0].message.content.trim();
let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  const match = content.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : content);
}
const projectId = $('Webhook').item.json.body.projectId || 'unknown';
return { json: { success: true, workflow: 'pitch-flow', projectId, generatedAt: new Date().toISOString(), data: parsed } };
